# Privacy Policy and Terms text. Built from site.config.json so it matches what the site really does. Edit, then run: python3 build.py
def privacy(x):
    e = f'<a href="mailto:{x["email"]}">{x["email"]}</a>'
    third = ["our hosting provider (it receives standard server logs)"]
    if x["api"]: third.append("our email delivery provider (Resend), which delivers your enquiry to our inbox")
    if x["turnstile"]: third.append("Cloudflare Turnstile, which checks that a form is sent by a person")
    third.append("WhatsApp (Meta), only if you choose to send an enquiry through it")
    if x["ga4"]: third.append("Google Analytics, only if you accept analytics")
    if x["plausible"]: third.append("Plausible Analytics, only if you accept analytics")
    s = [("Who we are", f'<p>Hei Digi is a digital marketing agency in {x["city"]}, {x["region"]}, India. This policy explains what personal information this website handles and why. Contact: {e}.</p>'),
    ("What we collect", '<ul><li><b>Enquiry details you type into the form:</b> name, phone number, and optionally email, company, service, budget range and message.</li><li><b>Server logs:</b> like most websites, our hosting provider records technical data such as IP address, browser type and the page requested, for security and reliability.</li>' +
      ('<li><b>Analytics, only if you accept:</b> which pages are viewed and which contact buttons are clicked, plus basic device and browser information. Nothing is collected for analytics unless you choose Accept.</li><li><b>Your consent choice</b> is saved in your browser (local storage) so we do not ask repeatedly.</li>' if x["analytics"] else '<li><b>Analytics:</b> this site does not currently use analytics or advertising cookies.</li>') + '</ul><p>We do not ask for payment details, identity numbers or other sensitive information through this website. Please do not send them in the message box.</p>'),
    ("How enquiries reach us", ('<p>When you submit the form, your details are sent securely to a function on our website, checked for spam, and emailed to us. The website does not keep a database of enquiries: they exist in our email inbox. If sending fails, the form tells you and offers WhatsApp, phone and email instead.</p><p>You can also contact us directly by WhatsApp, phone or email.</p>' if x["api"] else '<p>The form does not send your details to a database. When you submit it, your message opens in WhatsApp (or you can use email or phone). It is sent only when you press Send in WhatsApp, and WhatsApp then handles it under its own privacy policy. Nothing you type into the form is stored by this website.</p>')),
    ("How we use your information", '<p>To reply to your enquiry, prepare a quote, deliver services you ask for, keep business records, protect the website from abuse, and' + (' improve the site if you accepted analytics.' if x["analytics"] else ' meet legal obligations.') + ' We do not sell your information and we do not use enquiry details for third-party advertising.</p>'),
    ("Who else handles it", "<p>We use service providers to run the website and handle enquiries:</p><ul>" + "".join(f"<li>{t}</li>" for t in third) + "</ul><p>We may also disclose information when the law requires it.</p>"),
    ("How long we keep it", "<p>We keep enquiry details for as long as needed to respond and, if you become a client, to deliver and document the work. You can ask us to delete an enquiry at any time.</p>"),
    ("Your choices and rights", f'<p>You can ask us to tell you what we hold about you, correct it, or delete it, and you can withdraw consent you gave us. Email {e} and we will respond. This policy is intended to reflect, where applicable, India\'s Digital Personal Data Protection Act, 2023, the Information Technology Act, 2000 and applicable rules. The laws, commencement provisions and our actual operating practices should be reviewed by an Indian lawyer before publication.</p>' + ('<p>To change your analytics choice, use the Privacy settings link at the bottom of any page.</p>' if x["analytics"] else "")),
    ("Security", "<p>We use HTTPS, restrict what the website is allowed to load, and keep the amount of data we collect small. No method of transmission or storage is completely secure, so we cannot guarantee absolute security.</p>"),
    ("Children", "<p>This website is for businesses and professionals. It is not directed at children under 18.</p>"),
    ("Links to other sites", "<p>Our pages link to third-party sites such as WhatsApp. Their privacy practices are theirs, not ours.</p>"),
    ("Changes and questions", f'<p>We will post updates on this page and change the date above. Questions or complaints about privacy: {e}.</p>')]
    return s
def terms(x):
    e = f'<a href="mailto:{x["email"]}">{x["email"]}</a>'
    return [("Using this website", f'<p>By using this website you agree to these terms. If you do not agree, please do not use it. Hei Digi is a digital marketing agency in {x["city"]}, {x["region"]}, India. Contact: {e}.</p>'),
    ("Information on this site", "<p>The pages describe our services in general terms. They are not an offer or a quote. A service engagement starts only when we agree scope, price and timing with you in writing (a quote, proposal or agreement), and those written terms apply to the work.</p>"),
    ("No guarantees of results", "<p>Marketing results depend on many things outside our control, including your offer, budget, competition, and the rules and algorithms of platforms such as Google and Meta. We do not guarantee rankings, followers, leads, sales or any specific return.</p>"),
    ("Advertising spend and platforms", "<p>Where we run paid campaigns, the advertising budget is paid by you directly to the platform and is separate from our service fee. Platforms can reject ads or restrict accounts under their own policies, and we are not responsible for those decisions.</p>"),
    ("Your responsibilities as a client", "<p>You will give us accurate information, confirm that you have the right to use any logos, photos, text or other material you provide, approve content before it is published, and make sure your promotions follow the laws and professional rules that apply to your business (for example, advertising rules for healthcare professionals).</p>"),
    ("AI-assisted work", "<p>We may use AI tools for ideas, drafts, research and some visuals. People review and edit the work, and you approve it before publication. We label AI-generated visuals where it matters.</p>"),
    ("Intellectual property", "<p>The design, text and code of this website belong to Hei Digi or its licensors and may not be copied without permission. Ownership and licences for work we create for clients are set out in the written agreement for that work.</p>"),
    ("Client names and work", f'<p>This site lists businesses we have worked with and may show examples of our work. If you are a listed client and want your name or work changed or removed, email {e} and we will act on it.</p>'),
    ("Acceptable use", "<p>Do not misuse this website: no attempts to break or overload it, to access it without permission, or to send spam or unlawful content through the contact form.</p>"),
    ("Links to other sites", "<p>We link to third-party sites and are not responsible for their content or practices.</p>"),
    ("Disclaimer and liability", "<p>This website is provided as is. To the extent the law allows, Hei Digi is not liable for indirect or consequential loss arising from use of the website, and our liability for services is limited as set out in the written agreement for those services.</p>"),
    ("Privacy", '<p>How we handle personal information is explained in our <a href="/privacy/">Privacy Policy</a>.</p>'),
    ("Changes", "<p>We may update these terms. The date at the top shows the latest version. Continued use after a change means you accept it.</p>"),
    ("Governing law", f'<p>These terms are governed by the laws of India. Courts at {x["city"]}, {x["region"]} have jurisdiction over disputes, subject to any mandatory rights you have.</p>')]
